INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u07-l01','course-a1-foundations','jobs-and-workplaces-a1','Jobs and Workplaces','Name common jobs and say where people work.','A1',31,1,'published');
