('a1-u07-l01-q02','a1-u07-l01','multiple_choice','A teacher works at a ___.','[{"id":"a","text":"school"},{"id":"b","text":"airport"},{"id":"c","text":"restaurant"}]','a','Teachers work at schools.',2),
('a1-u07-l01-q03','a1-u07-l01','multiple_choice','Which job prepares food in a restaurant?','[{"id":"a","text":"chef"},{"id":"b","text":"nurse"},{"id":"c","text":"driver"}]','a','A chef prepares food.',3),
('a1-u07-l01-q04','a1-u07-l01','multiple_choice','What does a bus driver do?','[{"id":"a","text":"drives a bus"},{"id":"b","text":"teaches English"},{"id":"c","text":"sells medicine"}]','a','A bus driver drives a bus.',4);
